const channels={all:'전체 채널',blog:'블로그',instagram:'인스타그램',threads:'스레드',xiaohongshu:'샤오홍슈',tiktok:'틱톡',youtube:'유튜브 쇼츠'};
const types={issue:'빠른 정보·이슈',info:'여행 정보·날씨',review:'여행 후기',sponsor:'협찬·체험단',affiliate:'상품·제휴',video:'짧은 영상',social:'SNS 글'};
const publicationLanes={manual:'직접 작성한 여행 글','asia-issue':'아시아 이슈 자동 글','brand-shopping':'브랜드 커넥트 자동 글'};

function refreshRow(row){return `<article class="recommendation-row"><div class="recommendation-main"><div class="pill-list"><span class="badge gold">${esc(row.basisLabel)} 감소 관측</span><span class="badge gray">${esc(row.source)}</span>${row.region?`<span class="badge gray">${esc(row.region)}</span>`:''}</div><h3>${esc(row.title)}</h3><div class="refresh-comparison"><div><small>이전 높은 구간 · 관측일 평균</small><strong>${row.peak.average.toFixed(1)}</strong><small>${esc(row.peak.start)} ~ ${esc(row.peak.end)}<br>${row.peak.days} / 14일 자료</small></div><span aria-hidden="true">→</span><div><small>최근 구간 · 관측일 평균</small><strong>${row.recent.average.toFixed(1)}</strong><small>${esc(row.recent.start)} ~ ${esc(row.recent.end)}<br>${row.recent.days} / 14일 자료</small></div><span class="badge gold">${(row.decline*100).toFixed(0)}% 감소</span></div><p>${row.actions.map(esc).join('<br>')}</p>${row.cautions.map(c=>`<p class="recommendation-caution">${esc(c)}</p>`).join('')}</div><div class="recommendation-actions">${btn('chooseRefresh',row.activeItemId?'기획 이어 쓰기':'재작성 기획 만들기','primary tiny',`data-id="${esc(row.id)}" data-fingerprint="${esc(row.fingerprint)}"`)}${row.url?`<a class="refresh-original" href="${esc(row.url)}" target="_blank" rel="noopener">원본 글 보기 ↗</a>`:btn('writeItem','원본 기록','tiny',`data-id="${esc(row.itemId)}"`)}</div></article>`;}
function refreshPanel(compact=false){const rows=compact?refresh.candidates.slice(0,2):refresh.candidates;return panel('다시 꺼내볼 과거 글',`<div class="panel-body">${!compact?refresh.warnings.map(w=>`<div class="notice">${esc(w)}</div>`).join(''):''}${rows.length?rows.map(refreshRow).join(''):empty(refresh.coverage.comparablePosts?'비교 가능한 자료에서 재작성 기준에 해당하는 글이 없어요.':'글별 성과 자료가 쌓이면 과거의 높은 유입과 최근 흐름을 비교해요.',btn('importMetrics','글별 성과 가져오기','tiny'))}${!compact?`<details class="details"><summary>추천 기준 확인</summary><p class="muted">발행 후 28일 이상 지난 글을 살펴봐요. 최근 14일과 이전 6개월 안의 14일 구간에 각각 최소 7일의 실제 자료가 필요합니다. 이전 관측일 평균이 5 이상이고 최근 평균이 절반 이하일 때 후보로 보여요.<br>동일 글·출처·지표로 비교하며 누락 날짜를 0으로 채우지 않아요. 조회수로 검색 유입 감소를 단정하지 않고, 재작성의 효과도 따로 확인합니다.</p></details>`:''}</div>`,compact?btn('navigate','재작성 추천 전체 →','ghost tiny','data-route="refresh"'):btn('refreshRecommendations','새로 확인','tiny'),true);}
function refreshPage(){const plans=refresh.plans;return head('과거 글 재작성','줄어든 유입을 확인하고, 다시 다룰 가치가 있는 글을 골라요.',btn('navigate','유입 검색어 추천','','data-route="recommendations"')+btn('importMetrics','성과 CSV 가져오기'))+refreshPanel()+postStatsPanel()+panel('재작성 기획과 이후 흐름',plans.length?`<div class="table-scroll"><table><thead><tr><th>재작성 기획</th><th>상태</th><th>기획 당시 관측 평균</th><th>새 글 발행 후 실측</th><th>작업</th></tr></thead><tbody>${plans.map(p=>`<tr><td>${esc(p.title)}<span class="table-sub">원본: ${esc(p.originalTitle)} · 기획 ${esc(p.selectedAt.slice(0,10))}</span></td><td>${statusBadge(p.status)}</td><td>${p.evidence.peak.average.toFixed(1)} → ${p.evidence.recent.average.toFixed(1)}<span class="table-sub">${esc(p.evidence.basisLabel)} · ${esc(p.evidence.source)}</span></td><td>${p.postTotal===null?'집계 대기':fmt(p.postTotal)}${p.postTotal!==null?`<span class="table-sub">${p.postDays}일 관측 · 평균 ${p.postAverage.toFixed(1)}${p.postDays<7?' · 비교 자료 부족':''}</span>`:''}</td><td>${p.status!=='글감 삭제됨'?btn('writeItem','기획 열기','tiny',`data-id="${esc(p.newItemId)}"`):''}</td></tr>`).join('')}</tbody></table></div><p class="panel-body muted">원본의 원고·게시 상태·일정은 그대로 보관합니다. 새 글 발행 후 첫 14일의 같은 출처·지표만 따로 보여요. 서로 다른 글의 수치를 재작성의 인과 효과로 단정하지 않아요.</p>`:empty('재작성 기획을 선택하면 추천 근거와 진행 상태가 여기에 남아요.'));}

function publicationLocal(at){if(!at)return '';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(at));const value=t=>parts.find(p=>p.type===t).value;return `${value('year')}-${value('month')}-${value('day')}T${value('hour')}:${value('minute')}`;}
function publicationWhen(at){return publicationLocal(at).replace('T',' ')+' · 한국 시간';}
function publicationTone(status){return status==='게시 확인됨'?'green':['확인 필요','예약 확인됨'].includes(status)?'gold':'gray';}
function publicationWriterPanel(itemId){const jobs=publishing.jobs.filter(j=>j.itemId===itemId&&j.status!=='취소');if(!jobs.length)return '';return panel('이 글의 발행 준비',`<div class="panel-body">${jobs.slice(0,3).map(j=>`<div class="mini-row"><div><span class="badge ${publicationTone(j.status)}">${esc(j.status)}</span><p>${esc(publicationWhen(j.scheduledAt))}</p>${j.checks.issues.map(x=>`<p class="recommendation-caution">${esc(x)}</p>`).join('')}</div>${btn('publicationDetail','상세 보기','tiny',`data-id="${j.id}"`)}</div>`).join('')}</div>`,btn('navigate','발행 관리 →','ghost tiny','data-route="publishing"'));}
function automaticPreparationPanel(){const items=S.items.filter(i=>i.automaticResearch);return panel('자동 글 제작',items.length?`<div class="panel-body">${items.slice(0,10).map(i=>`<div class="mini-row"><div><strong>${esc(i.title)}</strong><p>${esc(publicationLanes[i.automaticLane])} · ${esc(i.date)} 01:00 · ${esc(i.automaticResearch.status)} · 사진 ${(i.attachmentIds||[]).length}장</p><p>${esc(i.automaticResearch.reason)}</p><details class="details"><summary>확인한 공식 자료 ${i.automaticResearch.sources.length}개</summary>${i.automaticResearch.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a></p>`).join('')}</details></div>${btn('writeItem','원고·사진 보기','tiny',`data-id="${esc(i.id)}"`)}</div>`).join('')}<p class="muted">조사·원고·사진을 보관한 상태와 네이버에서 확인한 예약 결과를 따로 표시해요.</p></div>`:empty('공식 자료와 이용 가능한 사진을 확인한 자동 글 기획이 여기에 쌓여요.'));}
function publicationPage(){
 const jobs=publishing.jobs,access=publishing.access;
 return head('발행 관리','준비한 원고와 실제 네이버 결과를 함께 확인해요.',btn('refreshPublication','새로 확인')+btn('newPublication','+ 발행 준비','primary'))+
 (connections.artifact?panel('네이버에 올리는 방법',`<div class="panel-body"><ol class="steps-list"><li>원고를 다 쓰면 <strong>+ 발행 준비</strong>로 발행 시각을 정해요.</li><li>목록의 <strong>예약 꾸러미</strong>를 열어 제목·서식 본문·사진·태그를 차례로 복사해 네이버 편집기에 붙여넣고, 네이버의 예약 발행을 걸어요.</li><li>예약을 마치면 <strong>예약 완료 기록</strong>, 올라간 뒤에는 <strong>게시 확인</strong>에 게시글 링크를 남겨요. 그래야 성과·퀘스트에 반영돼요.</li></ol><p class="muted">네이버는 글쓰기 API가 없어서 사이트가 직접 올리지 않아요. 꾸러미 안의 ‘Claude in Chrome 지시문’을 쓰면 Claude가 내 브라우저에서 붙여넣기를 도와요(올리기 전 직접 확인).</p></div>`):automaticPreparationPanel()+panel('네이버 연결 상태',`<div class="panel-body"><div class="mini-row"><div><strong>글쓰기 화면</strong><p>${esc(access?.message||'글쓰기 화면 접근을 아직 확인하지 못했어요.')}</p><p>${access?esc(publicationWhen(access.checkedAt)):'통계 연결과 글쓰기 연결을 각각 확인해요.'}</p></div><span class="badge ${publishing.editorReady?'green':'gold'}">${publishing.editorReady?'접근 확인':'접근 확인 필요'}</span></div><div class="mini-row"><div><strong>새벽 1시 자동 글</strong><p>아시아 이슈 1개 · 브랜드 커넥트 1개 · 직접 여행 글과 별도</p></div><span class="badge gray">실행 예약 미연결</span></div><p class="muted">네이버는 글쓰기 API가 없어 사이트가 직접 올리지는 못해요. 발행 준비 목록의 ‘예약 꾸러미’로 제목·서식 본문·사진·태그를 옮기고 네이버 편집기의 예약 발행을 쓰면 돼요. 예약을 마치면 ‘예약 완료 기록’, 올라간 뒤엔 ‘게시 확인’에 링크를 남겨 주세요.</p>${access?.runUrl?`<a href="${esc(access.runUrl)}" target="_blank" rel="noopener">접근 확인 기록 보기</a>`:''}</div>`))+
 `<section class="panel stats"><div class="stat"><span class="label">준비·대기</span><strong>${jobs.filter(j=>['준비 중','발행 대기'].includes(j.status)).length}개</strong><small>검수 결과와 사진 확인</small></div><div class="stat"><span class="label">네이버 예약 확인</span><strong>${jobs.filter(j=>j.status==='예약 확인됨').length}개</strong><small>실제 예약 목록 확인 기준</small></div><div class="stat"><span class="label">게시 확인</span><strong>${jobs.filter(j=>j.status==='게시 확인됨').length}개</strong><small>실제 게시글 링크 확인 기준</small></div><div class="stat"><span class="label">결과 확인 필요</span><strong>${jobs.filter(j=>j.status==='확인 필요').length}개</strong><small>확인 전 중복 실행 없음</small></div></section>`+
 (()=>{const due=jobs.filter(j=>j.status==='예약 확인됨'&&new Date(j.scheduledAt)<new Date());return due.length?`<div class="notice"><strong>예약 시각이 지난 글 ${due.length}개</strong> · 네이버에 올라갔는지 보고 ‘게시 확인’에 게시글 링크를 남겨 주세요.</div>`:'';})()+panel('발행 준비 목록',jobs.length?`<div class="table-scroll"><table><thead><tr><th>콘텐츠</th><th>발행 시각</th><th>상태·검사</th><th>작업</th></tr></thead><tbody>${jobs.map(j=>`<tr><td class="title">${esc(j.title)}<span class="table-sub">${esc(publicationLanes[j.lane])} · 사진 ${j.imageCount}장</span></td><td class="nowrap">${esc(publicationWhen(j.scheduledAt))}</td><td><span class="badge ${publicationTone(j.status)}">${esc(j.status)}</span>${['준비 중','발행 대기'].includes(j.status)?j.checks.issues.map(x=>`<span class="table-sub recommendation-caution">${esc(x)}</span>`).join(''):j.message?`<span class="table-sub">${esc(j.message)}</span>`:''}${j.receipt?.postUrl?`<a class="table-sub" href="${esc(j.receipt.postUrl)}" target="_blank" rel="noopener">게시글 보기 ↗</a>`:''}</td><td><div class="row-actions">${btn('publicationDetail','상세','tiny',`data-id="${j.id}"`)}${btn('writeItem','원고','tiny',`data-id="${j.itemId}"`)}${['준비 중','발행 대기'].includes(j.status)?btn('naverPackage','예약 꾸러미','primary tiny',`data-id="${j.id}"`)+btn('cancelPublication','준비 취소','ghost tiny',`data-id="${j.id}"`):''}${j.status==='예약 확인됨'&&j.receipt?.method==='manual'||['준비 중','발행 대기'].includes(j.status)?btn('confirmPublished','게시 확인','tiny',`data-id="${j.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('완성 원고를 저장한 뒤 발행 준비를 시작해요.',btn('newPublication','첫 발행 준비','primary')));
}
function choosePublicationModal(){const items=S.items.filter(i=>i.channel==='blog'&&i.status!=='게시됨');if(!items.length){toast('네이버 글감을 먼저 저장해 주세요.');return;}modal('발행할 원고 선택',selectField('itemId','네이버 글감',Object.fromEntries(items.map(i=>[i.id,i.title])),items[0].id),'publicationSelect','<button type="submit" class="primary">원고 선택</button>');}
function publicationModal(itemId){
 const item=S.items.find(i=>i.id===itemId);if(!item){choosePublicationModal();return;}if(item.channel!=='blog'){toast('네이버 블로그 글을 선택해 주세요.');return;}
 const latest=publishing.jobs.find(j=>j.itemId===item.id&&['준비 중','발행 대기'].includes(j.status)),automatic=!!item.automatic;
 let scheduledAt=latest?publicationLocal(latest.scheduledAt):automatic?(item.date&&item.date>day?item.date:shifted(day,1))+'T01:00':item.date&&item.date>day?item.date+'T09:00':publicationLocal(new Date(Date.now()+10*60000));
 const lines=String(item.draft||'').trim().split('\n');if(lines[0]?.replace(/^#+\s*/,'')===item.title)lines.shift();const paragraphs=lines.join('\n').split(/\n\s*\n/).filter(x=>x.trim()).length;
 const files=(item.attachmentIds||[]).map(id=>S.files.find(f=>f.id===id)).filter(f=>f&&f.type.startsWith('image/'));
 modal('발행 준비',`<input type="hidden" name="itemId" value="${esc(item.id)}"><input type="hidden" name="requestId" value="${crypto.randomUUID()}"><div class="form-grid">${field('title','최종 제목',latest?.title||item.title,'text','required maxlength="200"')}${field('scheduledAt','발행 시각 · 한국 시간 (10분 단위)',scheduledAt,'datetime-local','required step="600"')}</div><p class="muted">${esc(publicationLanes[item.automaticLane||'manual'])}${automatic?' · 새벽 01:00':''} · ${paragraphs}개 문단${item.date?' · 글감 예정일 '+esc(item.date):''}</p><div class="notice">저장한 원고를 기준으로 준비해요. ${item.deadline?'협찬 마감 '+esc(item.deadline)+' · ':''}${item.embargo?'엠바고 '+esc(item.embargo.replace('T',' '))+' · ':''}원고를 수정하면 발행 준비도 다시 저장해야 해요.</div><h3>사진 순서와 위치</h3><p class="muted">0은 대표사진, 1은 첫 번째 문단 뒤예요. 위에서 아래 순서로 배치합니다.</p><div class="publication-images">${files.map((f,n)=>{const old=latest?(S.publishJobs||[]).find(j=>j.id===latest.id)?.images.find(x=>x.fileId===f.id):null;return `<section class="publication-image"><img src="/api/files/${esc(f.id)}" alt="${esc(f.name)}"><div><label class="check-row"><input type="checkbox" name="include-${f.id}" ${!latest||old?'checked':''}>${esc(f.name)} 사용</label><div class="form-grid">${field('position-'+f.id,'문단 뒤',old?.afterParagraph??(n===0?0:Math.min(n,paragraphs)),'number',`min="0" max="${paragraphs}" required`)}${selectField('rights-'+f.id,'이미지 이용 권한',{unknown:'확인 필요',own:'직접 촬영',licensed:'이용 허락·라이선스', 'seller-authorized':'판매자 이용 허락',generated:'생성한 이미지'},old?.rights||'unknown')}${field('license-'+f.id,'이용 근거 링크 (허락·라이선스)',old?.licenseUrl||'','url')}${field('caption-'+f.id,'사진 설명 (선택)',old?.caption||'')}</div></div></section>`;}).join('')||'<div class="notice">첨부한 이미지가 없어요. 글쓰기 작업실의 사진·자료에서 올려 주세요. 자동 글은 사진 한 장 이상이 필요해요.</div>'}</div><label class="check-row"><input name="reviewed" type="checkbox" ${latest&&(S.publishJobs||[]).find(j=>j.id===latest.id)?.reviewed?'checked':''}>실제 경험·최신 정보·협찬 가이드라인과 고지를 검수했어요</label><small class="muted">준비 저장 후 검사 결과를 확인할 수 있어요. 실제 예약·발행은 글쓰기 연결과 실행 서비스가 필요합니다.</small>`,'publication','<button type="submit" class="primary">발행 준비 저장</button>');
}
