 const behind=(n>=4?'<path d="M52 97 30 152h90L98 97Z" fill="#a9cbe0" opacity=".75" stroke="#7fa7bf" class="cape"/>':'')+(n>=1?'<rect x="94" y="99" width="22" height="28" rx="7" fill="#e9c98f" stroke="#a88a56" stroke-width="1.5"/><path d="M98 108h14" stroke="#a88a56"/>':'');
 const front=(n>=2?'<path d="m67 102 10 8 9-9M58 112l33 17" stroke="#a0825f" stroke-width="4"/><rect x="62" y="112" width="26" height="17" rx="3" fill="#627d8f" stroke="#456477"/><rect x="66" y="109" width="8" height="4" rx="1" fill="#7c9ba9"/><circle cx="78" cy="120" r="6" fill="#b8dbea" stroke="#d9eef9" stroke-width="2"/><circle cx="84" cy="115" r="1.4" fill="#fff" class="flash"/>':'')+(n>=3?'<g class="notebook"><rect x="30" y="111" width="15" height="19" rx="2" fill="#f6efe2" stroke="#a0825f" stroke-width="1.3"/><path d="M33 116h9M33 120h9M33 124h6" stroke="#c6ae8a"/></g>':'')+(n>=5?'<g class="aura"><path d="m24 40 1.6-4 1.6 4 4 1.6-4 1.6-1.6 4-1.6-4-4-1.6Z" fill="#e8d7ad"/><path d="m128 98 1.2-3 1.2 3 3 1.2-3 1.2-1.2 3-1.2-3-3-1.2Z" fill="#e8d7ad"/><path d="m114 124 18-30" stroke="#d8c08a" stroke-width="2.4" stroke-linecap="round"/><path d="m132 94-5 2 3 3Z" fill="#f2e3b8" stroke="#c3a96b"/></g>':'');
