function ask(message,ok='확인',cancel='취소'){return new Promise(resolve=>{const box=document.createElement('div');box.className='ask-backdrop';box.innerHTML=`<div class="ask-dialog" role="alertdialog" aria-modal="true" aria-labelledby="ask-text"><p id="ask-text"></p><div class="writing-actions"><button type="button" data-ask="no">${esc(cancel)}</button><button type="button" class="primary" data-ask="yes">${esc(ok)}</button></div></div>`;box.querySelector('#ask-text').textContent=message;const done=v=>{box.remove();resolve(v);};box.addEventListener('click',e=>{const b=e.target.closest('[data-ask]');if(b)done(b.dataset.ask==='yes');else if(e.target===box)done(false);});box.addEventListener('keydown',e=>{if(e.key==='Escape')done(false);});document.body.append(box);box.querySelector('[data-ask="yes"]').focus();});}
function celebrate(){const L=questBoard?.level;if(!L)return;const box=document.createElement('div');box.className='levelup';box.setAttribute('role','status');box.innerHTML=`<div class="levelup-card"><div class="levelup-chara">${character()}</div><span class="level">LEVEL UP</span><h2>Lv. ${L.level} ${esc(L.stage.title)}</h2><p>${esc(L.stage.outfit)}와 함께해요.</p><button type="button" class="primary">좋아요</button></div>${Array.from({length:14},(_,i)=>`<i style="--i:${i}"></i>`).join('')}`;const close=()=>box.remove();box.querySelector('button').onclick=close;box.addEventListener('click',e=>{if(e.target===box)close();});document.body.append(box);box.querySelector('button').focus();}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
async function api(path,body){const r=await fetch(path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw new Error('서버 응답을 확인할 수 없어요.');}if(r.status===401){location.href='/';throw new Error('다시 로그인해 주세요.');}if(!r.ok)throw new Error(data.error||'작업을 완료하지 못했어요.');return data;}
async function load(){const data=await api('/api/state');S=data.state;trends=data.trends||{rows:[],sources:[],warnings:[],providers:[]};formatting=data.formatting||{profiles:[],studies:[]};naverPosts=data.naverPosts||{posts:[],stats:null,sync:null};analyticsRows=data.analytics||[];day=data.day;quests=data.quests;questBoard=data.questBoard||null;commerce=data.commerce||commerce;styleInfo=data.style||styleInfo;seasons=data.seasons||[];earnData=null;productResult=null;connections=data.connections;recommendations=data.recommendations||{existing:[],ideas:[],warnings:[]};publishing=data.publishing||{jobs:[],access:null};refresh=data.refresh||{candidates:[],plans:[],coverage:{},warnings:[]};document.body.classList.toggle('motion-off',!S.settings.motion);if(!calendarMonth)calendarMonth=day.slice(0,7);clearTimeout(nightTimer);if(extHelloSent)nightTimer=setTimeout(()=>nightDraftSync().catch(()=>{}),4000);if(!extHelloSent){extHelloSent=true;setTimeout(()=>{installPromptOnce().catch(()=>{});extHello();extApplyApi();nightDraftSync().catch(()=>{}).finally(()=>autoDraftOnce().catch(()=>{}).finally(()=>autoRekeyOnce().catch(()=>{}).finally(()=>autoStyleOnce().catch(()=>{}).finally(()=>autoWeeklyOnce().catch(()=>{})))));},1500);}}
async function act(action,extra={},message='저장했어요.'){const r=await api('/api/action',{action,...extra});await load();if(message)toast(message);return r.result;}
function navigate(r,id){writerBuffer=null;writerPromptChoice=null;promptEditing=null;route=r;editing=id||null;filterText='';filterStatus='';contentPage=0;location.hash=r+(id?'/'+id:'');render();document.querySelector('.sidebar')?.classList.remove('open');window.scrollTo(0,0);if(r==='writer')writerBaseline=JSON.stringify(getWriter());}
function navigation(){const groups=[['',[['home','home']]],['찾기·기획',[['recommendations','search'],['contents','folder']]],['쓰기',[['writer','pen']]],['일정·발행',[['calendar','calendar'],['publishing','shield'],['sponsors','users']]],['수익·성과',[['commerce','coin'],['analytics','chart']]],['',[['quests','star']]]];return `<aside class="sidebar"><div class="brand">써즈의 동네방네<small>CONTENT ADVENTURE GUILD</small></div><select aria-label="채널 선택" id="channel" class="channel-select">${Object.entries(channels).map(([v,n])=>`<option value="${v}" ${v===channel?'selected':''}>${n}</option>`).join('')}</select><nav class="nav">${groups.map(([g,navs])=>(g?`<span class="nav-group">${g}</span>`:'')+navs.map(([r,i])=>btn('navigate',icon(i)+paths[r],route===r||r==='recommendations'&&route==='refresh'?'active':'',`data-route="${r}"`)).join('')).join('')}</nav><nav class="nav secondary">${[['learning','book'],['settings','gear']].map(([r,i])=>btn('navigate',icon(i)+paths[r],route===r?'active':'',`data-route="${r}"`)).join('')}</nav><div class="profile"><div class="profile-face">${character()}</div><div><strong>${esc(S.settings.characterName)} · Lv. ${1+Math.floor(S.xp/150)}</strong><small>${btn('navigate','성장 보기 →','ghost tiny',`data-route="quests"`)}</small></div></div></aside>`;}
function render(){const unread=S.events.filter(e=>!e.read).length;document.getElementById('app').innerHTML=navigation()+`<div class="shell"><header class="topbar"><div class="crumb">${btn('menu',icon('menu'),'ghost mobile-only')}<span>${channels[channel]}</span><span>/</span><strong>${paths[route]}</strong></div><div class="tools"><span class="muted">${day.replaceAll('-','.')} · KST</span>${btn('notifications',icon('bell')+(unread?'<span class="dot"></span>':''),'ghost bell','aria-label="알림 센터"')}<div class="avatar-letter">S</div></div></header><main class="content">${pages[route]()}</main></div>`;if(drawerOpen)drawer();if(route==='writer'&&editing&&S.items.find(i=>i.id===editing)?.draft)refreshFormattingPreview().catch(()=>{});requestVisibleTrends();}
function head(title,subtitle,actions=''){return `<div class="page-head ${route==='writer'?'writer-head':''}"><div><div class="eyebrow">SUZZ'S WORKSPACE</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;}
function panel(title,body,actions='',game=false){return `<section class="panel ${game?'game':''}"><header class="panel-title"><h2>${game?'<span class="rune">✧</span>':''}${title}</h2>${actions}</header>${body}</section>`;}
function empty(text,action=''){return `<div class="empty">${icon('book')}<div>${text}</div>${action?'<div class="gap"></div>'+action:''}</div>`;}
function itemTable(items,{compact=false}={}){return !items.length?empty('아직 이 목록에 글감이 없어요.',btn('newItem','글감 추가','primary')):`<div class="table-scroll"><table><thead><tr><th>콘텐츠</th><th>지역·채널</th><th>상태</th><th>발행일</th><th>작업</th></tr></thead><tbody>${items.map(i=>`<tr><td class="title">${esc(i.title)}<span class="table-sub">${esc(types[i.type]||i.type)}${i.deadline?' · 마감 '+esc(dateText(i.deadline)):''}${i.locked?' · 일정 잠금':''}</span></td><td><span class="badge gray">${esc(i.region)}</span><span class="table-sub">${channels[i.channel]}</span></td><td>${statusBadge(i.status)}${i.needsRegionReview?'<span class="table-sub">지역 확인 필요</span>':''}</td><td class="nowrap">${dateText(i.date)}${i.originalDate&&!i.date?'<span class="table-sub">기존 '+dateText(i.originalDate)+'</span>':''}</td><td><div class="row-actions">${btn('writeItem',i.draft?'이어서 쓰기':'글쓰기','tiny primary',`data-id="${esc(i.id)}"`)}${btn('editItem',icon('gear'),'tiny ghost',`data-id="${esc(i.id)}" aria-label="글감 설정"`)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function questRows(list=questBoard?.daily||quests){return `<div class="quest-list">${list.map(q=>{const claimed=q.claimed??S.rewards.some(r=>r.key===q.key);return `<div class="quest ${q.done?'done':''} ${claimed?'claimed':''}">${btn('claimQuest',q.done?icon('check'):'','check',`data-key="${esc(q.key)}" ${!q.done||claimed?'disabled':''} aria-label="${esc(q.title)} 보상 받기"`)}<div class="quest-info"><strong>${esc(q.title)} ${q.optional?'<span class="badge gray">선택</span>':''}</strong><p>${esc(q.description)}${q.target&&q.current!=null?' · '+fmt(q.current)+'/'+fmt(q.target):''}${q.needsData?' · 네이버 7일 통계 필요':''}</p>${q.target&&q.current!=null?`<div class="progress thin"><span style="width:${Math.min(100,q.current/q.target*100)}%"></span></div>`:''}</div><span class="exp">${claimed?'획득 완료':'+'+q.xp+' EXP'}</span></div>`;}).join('')}</div>`;}
function home(){const current=visibleItems().filter(i=>i.date===day&&i.status!=='게시됨'),tomorrow=visibleItems().filter(i=>i.date===shifted(day,1)),weekly=S.items.filter(i=>i.type==='video'&&i.createdAt.slice(0,10)>=nowWeek()),level=1+Math.floor(S.xp/150),goal=S.settings.visitorGoal;return head(channel==='all'?'오늘의 모험과 작업':channels[channel]+' 매니저','작은 기록을 쌓아, 더 넓은 세상으로.',btn('newWriter',icon('pen')+'새 글 쓰기','primary'))+`<section class="hero"><div class="character">${character()}<span class="spark">✧</span><span class="character-label">Lv. ${questBoard?.level?.level||1} ${esc(charaStage().title)} · 오늘은 ${esc(charaMood().name)}</span></div><div><span class="level">Lv. ${level} · 여행 기록가</span><h2>${esc(S.settings.characterName)}님, 오늘도 함께 떠나요.</h2><p>${current.length?'오늘 예정된 콘텐츠는 '+current.length+'개예요. 하나씩 이어가 볼까요?':'오늘의 글감을 골라 작은 모험을 시작해요.'}<br>쉬어 가도, 쌓아온 성장은 사라지지 않아요.</p><div class="xp-line"><span>캐릭터 경험치</span><span>${S.xp%150} / 150 EXP</span></div><div class="progress"><span style="width:${S.xp%150/150*100}%"></span></div></div>${visitorGoalBox()}</section>`+`<section class="panel stats"><div class="stat"><span class="label">오늘 여행 글</span><strong>${current.filter(i=>i.channel==='blog'&&!i.automatic).length} / ${S.settings.dailyTarget}개</strong><small>직접 작업 · 밀리면 최대 4개</small></div><div class="stat"><span class="label">내일 콘텐츠</span><strong>${tomorrow.length}개</strong><small>사진·구성 미리 준비</small></div><div class="stat"><span class="label">주간 영상 원본</span><strong>${weekly.length} / ${S.settings.weeklyVideos}개</strong><small>쇼츠 · 틱톡 · 릴스 연결</small></div><div class="stat"><span class="label">오늘 올릴 SNS</span><strong>${visibleItems().filter(i=>i.date===day&&i.channel!=='blog'&&i.status!=='게시됨').length}개</strong><small>인스타 · 스레드 · 쇼츠</small></div></section>`+briefingPanel()+todayActions()+channelTabs()+((channel==='all'||channel==='blog')?(trends.rows?.length?trendPanel(true):'')+(recommendations.existing?.length||recommendations.ideas?.length?recommendationPanel(true):'')+keywordIdeaPanel():'')+((channel==='all'||channel==='blog')&&refresh.candidates.length?refreshPanel(true):'')+panel('오늘의 우선 작업',itemTable(current.slice(0,8))+`<div class="table-footer" data-action="navigate" data-route="calendar">발행 일정 전체 보기 →</div>`,btn('newItem','+ 글감 추가','tiny'),true)+((channel==='all'||channel==='blog')&&seasons.length?seasonPanel():'')+`<div class="grid-2">${panel('오늘의 퀘스트',`<div class="panel-body">${questRows()}</div>`,btn('navigate','성장 기록 →','ghost tiny','data-route="quests"'),true)}${panel('협찬·다음 준비',`<div class="panel-body"><div class="mini-list">${S.sponsors.filter(s=>s.stage!=='완료').slice(0,3).map(s=>`<div class="mini-row"><div><strong>${esc(s.title)}</strong><p>${esc(s.stage)} · 촬영 ${dateText(s.visitDate)} · 마감 ${dateText(s.deadline)}</p></div>${btn('editSponsor','열기 →','ghost tiny',`data-id="${s.id}"`)}</div>`).join('')||'<div class="muted">다가오는 협찬과 촬영을 등록해 보세요.</div>'}</div><div class="gap"></div>${btn('newSponsor','협찬 일정 추가','tiny')}</div>`,btn('navigate','전체 →','ghost tiny','data-route="sponsors"'))}</div>`;}
function channelTabs(){return `<div class="channel-tabs">${Object.entries(channels).map(([v,n])=>btn('channel',n+(v==='xiaohongshu'||v==='tiktok'||v==='youtube'?'<small>준비</small>':''),v===channel?'active':'',`data-channel="${v}"`)).join('')}</div>`;}
function contents(){const all=visibleItems().filter(i=>(!filterText||(i.title+' '+i.region+' '+i.topic).toLowerCase().includes(filterText.toLowerCase()))&&(!filterStatus||i.status===filterStatus));return head('콘텐츠 보관함','지역별 글감부터 사진·구성·발행 상태까지 한곳에서.',(connections.ai?btn('seriesPlan','시리즈 기획')+btn('batchDraft','초안 한 번에 쓰기'):'')+btn('bulkAdd','목록 붙여넣기')+btn('newItem','+ 글감 추가','primary'))+`<div class="filters"><input id="search" placeholder="제목·지역·소재 검색" value="${esc(filterText)}" aria-label="콘텐츠 검색"><select id="status-filter"><option value="">전체 상태</option>${['아이디어','초안 작성','예약됨','게시됨'].map(s=>`<option ${s===filterStatus?'selected':''}>${s}</option>`).join('')}</select><span class="count">${all.length}개</span></div>`+panel('글감 목록',itemTable(all.slice(contentPage*50,contentPage*50+50)),`<span class="muted">${contentPage+1} / ${Math.max(1,Math.ceil(all.length/50))}</span>`)+`<div class="head-actions">${btn('pagePrev','← 이전','',contentPage===0?'disabled':'')}${btn('pageNext','다음 →','',all.length<=(contentPage+1)*50?'disabled':'')}</div>`;}
function writerCounts(draft,title,minWords,ids,keyword,keywordCount){
 const lines=String(draft||'').trim().split('\n');
 if(lines[0]?.replace(/^#+\s*/,'')===String(title||'').trim())lines.shift();
 const body=lines.join('\n').trim(),withSpaces=Array.from(body).length,withoutSpaces=Array.from(body.replace(/\s/g,'')).length;
 const photos=new Set(ids||[]),photoCount=S.files.filter(f=>photos.has(f.id)&&String(f.type||'').startsWith('image/')).length;
 const min=Math.max(0,Number(minWords)||0),remaining=Math.max(0,min-withoutSpaces);
 const key=String(keyword||''),expected=Number(keywordCount),target=Number.isSafeInteger(expected)&&expected>0?expected:0;
 const titleHits=key.trim()?String(title||'').split(key).length-1:0,bodyHits=key.trim()?body.split(key).length-1:0,total=titleHits+bodyHits;
 const keywordSummary=key.trim()?`<br>메인 키워드 ‘${esc(key)}’ · 제목 ${fmt(titleHits)}회 + 본문 ${fmt(bodyHits)}회 = 총 ${fmt(total)}회${target?` · 목표 ${fmt(target)}회 · ${total===target?'횟수 충족':total<target?fmt(target-total)+'회 부족':fmt(total-target)+'회 초과'}`:' · 목표 횟수 미지정'}${titleHits?'':'<br>제목에 메인 키워드를 정확한 띄어쓰기로 넣어 주세요.'}${(()=>{const c=key.normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,''),m=(S.keywordMetrics||[]).find(x=>x.key===c);return m&&m.volume!=null?`<br>네이버 월 검색 ${fmt(m.volume)}회${m.compIdx?' · 광고 경쟁 '+esc(m.compIdx):''} <small>(${esc(String(m.updatedAt||'').slice(5,10))} 기준)</small>`:'';})()}`:'';
 return `본문 · 공백 포함 ${fmt(withSpaces)}자 / 공백 제외 ${fmt(withoutSpaces)}자 · 첨부 사진 ${fmt(photoCount)}장${min?`<br>본문 공백 제외 기준 최소 ${fmt(min)}자 · ${remaining?fmt(remaining)+'자 더 필요해요':'분량 충족'}`:''}${keywordSummary}`;
}
function refreshWriterCounts(){
 const form=document.getElementById('writer-form'),target=document.getElementById('writer-counts');
 if(!form||!target)return;
 target.innerHTML=writerCounts(form.elements.draft.value,form.elements.title.value,form.elements.minWords.value,JSON.parse(form.elements.attachmentIds.value||'[]'),form.elements.keyword.value,form.elements.keywordCount.value);
}
let seriesDraft=null;
function seriesModal(){seriesDraft=null;modal('시리즈 기획',`<p class="muted">주제 하나를 검색 의도가 겹치지 않는 여러 편으로 나눠요. 담아 둔 키워드·검색량과 이미 쓴 글을 참고해서 겹치는 편은 빼요. 결과를 보고 고른 편만 글감에 담아요.</p><div class="form-grid"><div class="form-group full"><label for="series-theme">주제</label><input id="series-theme" name="theme" placeholder="예: 제주 가을 여행, 다낭 가족여행 준비, 겨울 캠핑 장비" required></div><div class="form-group"><label for="series-count">편수</label><select id="series-count" name="count">${[3,4,5,6,8,10].map(n=>`<option ${n===5?'selected':''}>${n}</option>`).join('')}</select></div><div class="form-group"><label for="series-region">지역 (선택)</label><input id="series-region" name="region"></div><div class="form-group full"><label for="series-goal">목표 (선택)</label><input id="series-goal" name="goal" placeholder="예: 쇼핑커넥트 상품 연결, 검색 유입 늘리기, 협찬 제안용 포트폴리오"></div></div>${btn('seriesRun','Claude로 기획하기','primary',' type="button"')}<div id="series-preview"></div>`,'series','<button type="submit" class="primary" id="series-save" disabled>고른 편 글감에 담기</button>');}
function seriesPreview(p){return `<div class="notice"><strong>${esc(p.series||'시리즈')}</strong> · ${p.posts.length}편${p.warnings.length?`<ul>${p.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}</div><div class="mini-list">${p.posts.map((x,n)=>`<label class="mini-row check-row"><input type="checkbox" name="s-${n}" checked><div><strong>${n+1}. ${esc(x.title)}</strong><p class="muted">${esc(x.keyword)} · ${esc(types[x.type]||x.type)} · ${esc(x.angle)}</p><p class="muted">${esc(x.outline.join(' / '))}${x.needs.length?' · 준비: '+esc(x.needs.join(', ')):''}</p></div></label>`).join('')}</div><div class="form-grid"><div class="form-group"><label for="series-start">첫 발행일 (비우면 날짜 없이)</label><input type="date" id="series-start" name="startDate" value="${esc(shifted(day,1))}"></div><div class="form-group"><label for="series-every">간격</label><select id="series-every" name="every">${[[1,'매일'],[2,'이틀마다'],[3,'사흘마다'],[7,'매주']].map(([v,n])=>`<option value="${v}" ${v===2?'selected':''}>${n}</option>`).join('')}</select></div></div>`;}
// 키워드 검색량 바로 보기: 사이트 → 확장(써즈님 키) → 네이버 검색광고 API. 결과는 키워드 기록에도 남는다.
function extLookup(keywords){const id=crypto.randomUUID();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{lookupWaits.delete(id);reject(new Error('확장이 답하지 않아요. 확장이 켜져 있는지, 이 탭이 연결됐는지 확인해 주세요.'));},60000);lookupWaits.set(id,d=>{clearTimeout(timer);d.ok?resolve(d.item):reject(new Error(d.error||'조회하지 못했어요.'));});window.postMessage({type:'suzz-ext-lookup',id,keywords},'*');});}
function keywordLookupPanel(){const r=lookupResult;return panel('키워드 검색량 바로 보기',`<div class="panel-body"><form id="lookup-form" class="search-box"><input name="q" placeholder="쉼표로 최대 5개 · 예: 제주 억새, 다낭 여행" aria-label="조회할 키워드"><button class="primary" type="submit">${icon('search')} 조회</button></form><p class="muted">${extPresent?'':'브라우저 확장(1.3 이상)이 켜져 있고 검색광고 키를 넣어 두면 조회돼요. '}블랙키위 같은 분석 화면은 ${connections.ai?btn('keywordsReadOpen','캡처·복사로 담기','tiny',' type="button"'):'캡처로'} 넣거나, 확장의 ‘이 화면 보내기’로 보낼 수 있어요.</p>${r?`${r.errors?.length?`<div class="notice"><strong>못 불러온 것</strong><ul>${r.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<div class="mini-list">${r.keywords.map(k=>`<div class="mini-row"><div><strong>${esc(k.keyword)}</strong><p class="muted">${[k.volume!==null?'월 '+fmt(k.volume)+'회 (PC '+fmt(k.monthlyPc??0)+' · 모바일 '+fmt(k.monthlyMobile??0)+')':'검색량 없음',k.compIdx?'광고 경쟁 '+k.compIdx:'',k.lowPrice!==null?'쇼핑 최저가 '+won(k.lowPrice):''].filter(Boolean).map(esc).join(' · ')}</p></div><div class="writing-actions">${btn('keywordIdea','글감 담기','tiny primary',`data-q="${esc(k.keyword)}"`)}${connections.ai?btn('seriesFrom','시리즈','tiny',`data-q="${esc(k.keyword)}"`):''}</div></div>`).join('')||'<p class="muted">검색광고에서 이 키워드를 찾지 못했어요.</p>'}</div>${r.related?.length?`<p class="muted">연관 검색어 · 누르면 글감에 담겨요</p><div class="pill-list">${r.related.map(x=>btn('keywordIdea',esc(x.keyword)+(x.volume!==null?' · '+fmt(x.volume):'')+(x.compIdx?' · '+x.compIdx:''),'chip',`data-q="${esc(x.keyword)}"`)).join('')}</div>`:''}`:''}</div>`,'',true);}
let kwFilter='all',kwSort='score';const kwOpen=new Set();
function kwChange(k){return k.metric?.change!==null&&k.metric?.change!==undefined?{v:k.metric.change,label:'4주'}:k.metric?.volumeChange?{v:k.metric.volumeChange.change,label:k.metric.volumeChange.days+'일'}:null;}
function kwSeasonOnly(k){return k.from.length===1&&k.from[0]==='시즌'&&!k.metric&&!k.product;}
// 키워드 표: 글감 추천과 수익·상품 탭이 같은 표를 쓴다. 신호 없는 시즌 키워드는 표 아래 칩으로 모은다.
function keywordTable(all,{compact=false}={}){
 const seasonOnly=all.filter(kwSeasonOnly),main=all.filter(k=>!kwSeasonOnly(k));
 const filtered=main.filter(k=>kwFilter==='product'?k.product:kwFilter==='volume'?k.metric?.volume!=null:kwFilter==='gap'?!k.ownPosts:true);
 const sorted=[...filtered].sort((a,b)=>kwSort==='volume'?(b.metric?.volume??-1)-(a.metric?.volume??-1):kwSort==='commission'?(b.product?.commissionAmount??-1)-(a.product?.commissionAmount??-1):kwSort==='rising'?((kwChange(b)?.v??-9)-(kwChange(a)?.v??-9)):Number(b.golden)-Number(a.golden)||b.score-a.score).slice(0,compact?6:40);
 const chip=(k,n)=>btn('kwFilter',n,'chip'+(kwFilter===k?' active':''),`data-k="${k}"`),seg=(k,n)=>btn('kwSort',n,kwSort===k?'active':'',`data-k="${k}"`);
 const bar=(n,v)=>`<div class="pbar sm"><span>${n}</span><b>${v===undefined?'—':v}</b><i><em style="width:${v??0}%"></em></i></div>`;
 const row=k=>{const c=kwChange(k),open=kwOpen.has(k.keyword);return `<tr class="kw-row ${k.golden?'golden':''}"><td class="kw-name"><strong>${esc(k.keyword)}</strong>${k.golden?' <span class="badge gold">골든</span>':''}${k.ownPosts?` <span class="badge">내 글 ${k.ownPosts}</span>`:''}${k.writtenToday?' <span class="badge green">오늘 씀</span>':''}<br><small class="muted">${esc(k.from.join(' · '))}</small></td><td class="num"><span class="score-pill">${k.score}</span></td><td class="num">${k.metric?.volume!=null?fmt(k.metric.volume):'<span class="muted">—</span>'}</td><td>${k.metric?.compIdx?`<span class="badge ${k.metric.compIdx==='낮음'?'green':k.metric.compIdx==='높음'?'gold':''}">${esc(k.metric.compIdx)}</span>`:'<span class="muted">—</span>'}</td><td class="num">${c?`<span class="${c.v>=0?'up':'down'}">${c.v>=0?'▲':'▼'}${Math.abs(Math.round(c.v*100))}%</span> <small class="muted">${c.label}</small>`:k.mentions?`<small>뉴스 ${k.mentions}</small>`:'<span class="muted">—</span>'}</td><td>${k.season?`<small>${esc(k.season.title)}<br><span class="badge ${k.season.status==='한창'?'gold':''}">${esc(k.season.status)}</span></small>`:'<span class="muted">—</span>'}</td><td>${k.product?`<small>${esc(commerce.sources[k.product.source]||'')}</small><br>${k.product.commissionAmount!==null?'<strong>'+won(k.product.commissionAmount)+'</strong>':'<span class="muted">수수료 미확인</span>'}`:'<span class="muted">—</span>'}</td><td class="kw-act">${k.product?btn('keywordDraft',k.writtenToday?'한 편 더':'상품 글','primary tiny',`data-q="${esc(k.keyword)}" data-product="${esc(k.product.id)}"`):btn('keywordIdea','글감 담기','primary tiny',`data-q="${esc(k.keyword)}"`)}${connections.ai?btn('seriesFrom','시리즈','tiny',`data-q="${esc(k.keyword)}"`):''}${btn('kwToggle',open?'▴':'▾','ghost tiny',`data-q="${esc(k.keyword)}" aria-label="자세히"`)}</td></tr>${open?`<tr class="kw-detail"><td colspan="8"><div class="pbars inline">${bar('규모',k.parts.volume)}${bar('경쟁',k.parts.competition)}${bar('급등',k.parts.rising)}${bar('시즌',k.parts.season)}${bar('팔림',k.parts.sold)}${bar('수익',k.parts.revenue)}${bar('공백',k.parts.gap)}${bar('유입',k.parts.inflow)}</div><p class="muted">점수 = 신호마다 가중치(팔림 25 · 수익 20 · 급등 15 · 시즌 15 · 공백 15 · 규모 15 · 경쟁 10 · 유입 10). 확인되지 않은 신호는 중립 30. ${k.metric?.lowPrice!=null?'쇼핑 최저가 '+won(k.metric.lowPrice)+' · ':''}${k.metric?.updatedAt?'네이버 API '+esc(String(k.metric.updatedAt).slice(5,16).replace('T',' ')):'검색량 미연결'}</p></td></tr>`:''}`;};
 return `${compact?'':`<div class="kw-toolbar"><div class="pill-list">${chip('all','전체 '+main.length)}${chip('product','상품 있음 '+main.filter(k=>k.product).length)}${chip('volume','검색량 있음 '+main.filter(k=>k.metric?.volume!=null).length)}${chip('gap','내 글 없음 '+main.filter(k=>!k.ownPosts).length)}</div><div class="seg">${seg('score','점수순')}${seg('volume','검색량순')}${seg('rising','급등순')}${seg('commission','수수료순')}</div></div>`}${sorted.length?`<div class="table-wrap"><table class="kw-table"><thead><tr><th>키워드</th><th>점수</th><th>월 검색</th><th>경쟁</th><th>급등</th><th>시즌</th><th>상품·수수료</th><th></th></tr></thead><tbody>${sorted.map(row).join('')}</tbody></table></div>`:empty('이 조건에 맞는 키워드가 없어요.')}${seasonOnly.length&&!compact?`<p class="muted">시즌 키워드 (아직 검색량·상품 없음 · 누르면 글감에 담겨요)</p><div class="pill-list">${seasonOnly.slice(0,16).map(k=>btn('keywordIdea',esc(k.keyword),'chip',`data-q="${esc(k.keyword)}"`)).join('')}</div>`:''}${commerce.related?.length&&!compact?`<p class="muted">연관 검색어 (검색광고 월간 검색량)</p><div class="pill-list">${commerce.related.slice(0,12).map(r=>btn('keywordIdea',esc(r.keyword)+(r.volume!==null?' · '+fmt(r.volume):''),'chip',`data-q="${esc(r.keyword)}"`)).join('')}</div>`:''}`;
}
// 키워드 분석 화면(블랙키위 등) 캡처·복사 → Claude가 숫자를 옮김 → 확인 후 저장. 확장 '이 화면 보내기'로도 같은 창이 열린다.
