function keywordIdeaPanel(){const ks=commerce.keywords||[];if(!ks.length&&!(commerce.related||[]).length)return '';return panel('지금 쓰기 좋은 키워드',`<div class="panel-body"><p class="muted">네이버 검색량·광고 경쟁·급등·시즌·담은 상품·내 글 공백으로 매긴 순서예요. 상품이 있는 키워드는 ‘상품 글’로 바로 글감이 만들어져요.</p>${apiSyncNote()}${keywordTable(ks,{compact:route==='home'})}</div>`,route==='home'?btn('navigate','키워드 전체 →','ghost tiny','data-route="recommendations"'):btn('navigate','수익·상품 키워드 →','ghost tiny','data-route="commerce"'),true);}
// 홈·글감 추천 공용 '오늘 할 일' 등은 아래에 이어짐
