async function installPromptOnce(){if(promptInstalled||!S)return;promptInstalled=true;if((S.prompts||[]).some(p=>p.name==='써즈 전담 에디터 (25항목 전체)'))return;try{const r=await api('/api/action',{action:'installSuzzPrompt'});if(r.result?.installed){await load();render();toast('써즈님의 25항목 프롬프트 전문을 라이브러리에 넣고 기본으로 두었어요.');}}catch{}}
async function autoRekeyOnce(){if(rekeyDone||!connections.ai||!S)return;rekeyDone=true;const generic=k=>/상품|추천|찾기|목록|검색|인기|전체|홍보|베스트|best|결과/i.test(k||'')&&String(k||'').length<=12;const c=t=>String(t||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');if(!(S.products||[]).some(p=>generic(p.keyword)||!p.keyword||!c(p.name).includes(c(p.keyword))))return;try{const r=await api('/api/ai/rekey-products',{});if(r.changed){await load();productResult=null;render();toast('상품 '+r.changed+'개의 키워드를 품목으로 바꿨어요.');}}catch{}}
async function autoStyleOnce(){if(!connections.ai||S.settings.autoStyle===false||aiBusy||(styleInfo.fresh||0)<3)return;const key='suzz-style-day';let last='';try{last=localStorage.getItem(key)||'';}catch{}if(last===day)return;try{localStorage.setItem(key,day);}catch{}await runStyleUpdate(true);}
