function batchDraftModal(){const list=batchCandidates();modal('초안 한 번에 쓰기',list.length?`<p class="muted">원고가 비어 있는 글감을 골라 Claude가 차례로 초안을 써요. 다 쓴 초안은 바로 원고에 들어가고(원고가 있던 글은 건드리지 않아요), 글쓰기 작업실에서 확인·수정한 뒤 발행해요. 한 편에 1~2분쯤 걸려요. 창을 닫지 말아 주세요.</p><div class="form-group"><label for="batch-prompt">내 프롬프트</label><select id="batch-prompt" name="promptId">${promptOptions('review')}</select></div><div class="mini-list batch-list">${list.map((i,n)=>`<label class="mini-row check-row"><input type="checkbox" name="b-${esc(i.id)}" ${n<3?'checked':''}><div><strong>${esc(i.title)}</strong><p class="muted">${esc(i.date||'날짜 미정')} · ${esc(types[i.type]||'')} · ${esc(channels[i.channel])}${i.notes?' · 메모 있음':' · 메모 없음(초안이 짧을 수 있어요)'}</p></div><span class="batch-state" data-for="${esc(i.id)}"></span></label>`).join('')}</div><p id="batch-status" class="muted" role="status"></p>`:empty('원고가 비어 있는 글감이 없어요.'),'batchDraft',list.length?'<button type="submit" class="primary">고른 글 초안 쓰기</button>':'');}
async function runBatchDraft(form){if(aiBusy)throw new Error('AI 작성 중이에요. 잠시만 기다려 주세요.');const ids=[...form.querySelectorAll('input[type=checkbox][name^="b-"]:checked')].map(x=>x.name.slice(2));if(!ids.length)throw new Error('초안을 쓸 글을 골라 주세요.');const promptId=form.elements.promptId?.value||'',st=document.getElementById('batch-status');let ok=0,fail=0;aiBusy=true;form.querySelectorAll('input').forEach(x=>x.disabled=true);
 try{for(const [n,id] of ids.entries()){const mark=form.querySelector(`[data-for="${CSS.escape(id)}"]`);if(mark)mark.textContent='쓰는 중…';st.textContent=(n+1)+' / '+ids.length+' 쓰는 중';try{const r=await api('/api/ai/write',{requestId:crypto.randomUUID(),itemId:id,mode:'draft',autoApply:true,verifyLatest:false,promptId});const t=r.task;ok++;if(mark)mark.textContent=t.appliedAt?'✓ 원고에 넣음':t.status==='확인 필요'?'질문 있음':'결과 확인 필요';}catch(e){fail++;if(mark)mark.textContent='실패: '+e.message;if(/한도|429/.test(e.message))break;}}}
 finally{aiBusy=false;}await load();st.textContent='끝났어요 · 성공 '+ok+(fail?' · 실패 '+fail:'')+'. 글쓰기 작업실이나 콘텐츠에서 확인해 주세요.';const b=form.querySelector('button[type=submit]');if(b){b.textContent='닫기';b.dataset.done='1';}}
function snsSplitPanel(i){const made=S.items.filter(x=>x.parentId===i.id);return `<details class="details" ${made.length?'':'open'}><summary>SNS로 나눠 올리기${made.length?' · '+made.length+'곳 만듦':''}</summary><div class="detail-body"><p class="muted">이 원고로 채널별 게시물 초안을 만들어요. 블로그 발행 다음 날부터 하루에 한 채널씩 일정에 넣고, 올리기는 각 앱에서 직접 해요.</p><div class="pill-list">${[['instagram','인스타 캐러셀'],['threads','스레드'],['youtube','유튜브 쇼츠 대본'],['tiktok','틱톡 대본'],['xiaohongshu','샤오홍슈']].map(([v,n])=>{const done=made.some(x=>x.channel===v);return `<label class="check-row"><input type="checkbox" name="sns-${v}" ${done?'disabled checked':['instagram','threads'].includes(v)?'checked':''}>${n}${done?' ✓':''}</label>`;}).join('')}</div>${connections.ai?btn('snsSplit','Claude로 SNS 초안 만들기','tiny primary',' type="button"'):'<p class="muted">AI 연결이 필요해요.</p>'}${made.length?`<div class="mini-list">${made.map(x=>`<div class="mini-row"><div><strong>${esc(channels[x.channel])}</strong><p class="muted">${esc(x.title)} · ${esc(x.date||'날짜 미정')}</p></div>${btn('writeItem','열기','tiny',`data-id="${esc(x.id)}" type="button"`)}</div>`).join('')}</div>`:''}</div></details>`;}
